<template>
  <main class="operational-page">
    <header class="page-head"><div><h2>商城运营图片</h2><p>管理推荐、拼团和积分商城图片。按排序从高到低显示，同排序的新记录在前。</p></div><el-button :disabled="locked" @click="refresh">重新读取</el-button></header>
    <el-alert v-if="!canView || state.revoked" title="运营图片权限或登录状态已变化，请重新加载会话资料" type="warning" :closable="false" show-icon />
    <template v-else>
      <el-alert v-if="!canManage" title="当前账号仅可查看运营图片" type="info" :closable="false" show-icon />
      <el-alert v-if="state.error" :title="state.error" type="error" :closable="false" show-icon />
      <el-alert v-if="state.pending && !dialog && !bulkDialog" title="原提交结果尚未确认，已暂停新的写入" type="warning" :closable="false"><template #default><div class="recovery"><el-button :disabled="state.busy" @click="retryPending">重试原请求</el-button><el-button :disabled="state.busy" @click="readReceipt">读取提交回执</el-button></div></template></el-alert>
      <section class="content-panel">
        <div class="toolbar">
          <el-select v-model="state.name" aria-label="运营图片组" :disabled="locked" @change="changeGroup"><el-option v-for="option in options" :key="option.config_name" :value="option.config_name" :label="option.name" :disabled="!option.available" /></el-select>
          <el-select v-model="state.status" aria-label="运营图片状态筛选" placeholder="全部状态" :disabled="locked"><el-option label="全部状态" value="" /><el-option label="显示" :value="1" /><el-option label="隐藏" :value="0" /></el-select>
          <el-button :disabled="locked" @click="query">查询</el-button><el-button v-if="canManage" type="primary" :disabled="!workflow.writable() || formLoading" @click="openForm()">新增图片</el-button><el-button v-if="canManage" :disabled="!workflow.writable() || formLoading" @click="openBulk">整组编辑</el-button>
        </div>
        <p v-if="options.some(option=>!option.available)" class="hint">未启用的组缺少可用定义，需要维护人员先整理。此页面不会创建或改写字段定义。</p>
        <div v-loading="state.loading" class="table-scroll"><el-table :data="state.snapshot?.list || []" row-key="id" border empty-text="暂无运营图片">
          <el-table-column prop="id" label="ID" width="75" /><el-table-column label="图片" min-width="160"><template #default="{row}"><el-image v-if="row.img_preview" :src="row.img_preview" :preview-src-list="[row.img_preview]" preview-teleported fit="cover" class="banner-image" /><span v-else>无可读预览</span></template></el-table-column>
          <el-table-column prop="comment" :label="fieldLabel('comment','描述')" min-width="180" /><el-table-column prop="link" :label="fieldLabel('link','跳转链接')" min-width="240" /><el-table-column prop="sort" label="排序" width="80" />
          <el-table-column label="状态" width="95"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{ row.status===1?'显示':'隐藏' }}</el-tag></template></el-table-column>
          <el-table-column label="历史诊断" min-width="180"><template #default="{row}"><span>{{ row.issues.join('；') || '—' }}</span></template></el-table-column>
          <el-table-column v-if="canManage" label="操作" width="215"><template #default="{row}"><el-button link type="primary" :disabled="!workflow.writable() || !row.editable || formLoading" @click="openForm(row)">编辑</el-button><el-button link :disabled="!workflow.writable()" @click="setStatus(row)">{{ row.status===1?'隐藏':'显示' }}</el-button><el-button link type="danger" :disabled="!workflow.writable()" @click="remove(row)">删除</el-button></template></el-table-column>
        </el-table></div>
        <el-pagination :current-page="state.page" :page-size="20" :total="state.snapshot?.count || 0" layout="total, prev, pager, next" :disabled="locked" @current-change="pageChanged" />
      </section>
      <el-dialog v-model="dialog" :title="form.id?'编辑运营图片':'新增运营图片'" width="min(720px, calc(100vw - 24px))" :close-on-click-modal="false" :close-on-press-escape="!state.busy" :before-close="closeDialog">
        <el-alert v-if="state.pending" title="原提交结果尚未确认，请在此恢复" type="warning" :closable="false"><template #default><div class="recovery"><el-button :disabled="state.busy" @click="retryPending">重试原请求</el-button><el-button :disabled="state.busy" @click="readReceipt">读取提交回执</el-button></div></template></el-alert>
        <el-alert v-if="state.error" :title="state.error" type="error" :closable="false" />
        <el-form label-position="top" :disabled="locked">
          <el-form-item :label="fieldLabel('img','图片')" required><el-input v-model="form.img" maxlength="255" aria-label="图片稳定地址" placeholder="从图库选择或输入稳定地址" /><el-image v-if="draftPreview" :src="draftPreview" class="draft-image" fit="contain" /><SeckillActivityImagePicker title="选择运营图片" :disabled="locked" :editor-key="`${identity()}:${form.id}:${formRevision}`" @choose="chooseImage" /></el-form-item>
          <el-form-item :label="fieldLabel('comment','描述')" required><el-input v-model="form.comment" maxlength="500" aria-label="运营图片描述" /></el-form-item>
          <el-form-item :label="fieldLabel('link','跳转链接')" required><el-input v-model="form.link" maxlength="2048" aria-label="运营图片跳转链接" /><el-button :disabled="locked || !canSelectProduct" @click="openProducts(-1)">选择商品链接</el-button><p v-if="!canSelectProduct" class="hint">选择商品需要商品查看权限，也可填写已有合法站内路径。</p></el-form-item>
          <div class="form-grid"><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0" :max="2147483647" :precision="0" aria-label="运营图片排序" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status" aria-label="运营图片显示状态"><el-radio :value="1">显示</el-radio><el-radio :value="0">隐藏</el-radio></el-radio-group></el-form-item></div>
        </el-form><template #footer><el-button :disabled="state.busy" @click="cancelEditor">关闭</el-button><el-button type="primary" :disabled="!workflow.writable()" @click="save">保存图片</el-button></template>
      </el-dialog>
      <el-dialog v-model="bulkDialog" title="整组编辑运营图片" width="min(960px, calc(100vw - 24px))" :close-on-click-modal="false" :close-on-press-escape="!state.busy" :before-close="closeDialog">
        <el-alert title="保存会替换本组全部记录，并生成新ID；以下顺序即显示顺序，其他组不变" type="warning" :closable="false" />
        <el-alert v-if="state.pending" title="整组提交结果尚未确认，请在此恢复" type="warning" :closable="false"><template #default><div class="recovery"><el-button :disabled="state.busy" @click="retryPending">重试原请求</el-button><el-button :disabled="state.busy" @click="readReceipt">读取提交回执</el-button></div></template></el-alert>
        <el-alert v-if="state.error" :title="state.error" type="error" :closable="false" />
        <article v-for="(entry,index) in bulk" :key="entry.key" class="bulk-card"><header><strong>图片 {{ index+1 }}</strong><div><el-button :disabled="locked || index===0" @click="move(index,-1)">上移</el-button><el-button :disabled="locked || index===bulk.length-1" @click="move(index,1)">下移</el-button><el-button :disabled="locked" type="danger" @click="bulk.splice(index,1)">移除</el-button></div></header><el-form label-position="top" :disabled="locked"><el-form-item label="图片稳定地址" required><el-input v-model="entry.img" maxlength="255" /><SeckillActivityImagePicker title="选择运营图片" :disabled="locked" :editor-key="`${identity()}:${entry.key}`" @choose="(reference)=>entry.img=reference" /></el-form-item><el-form-item label="描述" required><el-input v-model="entry.comment" maxlength="500" /></el-form-item><el-form-item label="跳转链接" required><el-input v-model="entry.link" maxlength="2048" /><el-button :disabled="locked || !canSelectProduct" @click="openProducts(index)">选择商品链接</el-button></el-form-item><el-form-item label="状态"><el-radio-group v-model="entry.status"><el-radio :value="1">显示</el-radio><el-radio :value="0">隐藏</el-radio></el-radio-group></el-form-item></el-form></article>
        <p v-if="!bulk.length" class="hint">本组将清空，保存前会再次确认。</p><el-button :disabled="locked || bulk.length>=100" @click="addBulk">添加图片</el-button>
        <template #footer><el-button :disabled="state.busy" @click="cancelEditor">关闭</el-button><el-button type="primary" :disabled="!workflow.writable()" @click="saveBulk">保存整组</el-button></template>
      </el-dialog>
      <el-dialog v-model="productDialog" title="选择跳转商品" width="min(640px, calc(100vw - 24px))"><div class="toolbar"><el-input v-model="productKeyword" aria-label="搜索跳转商品" placeholder="搜索商品名称" /><el-button :disabled="productsLoading" @click="searchProducts">查询</el-button></div><el-alert v-if="productError" :title="productError" type="error" :closable="false" /><el-table :data="products" v-loading="productsLoading"><el-table-column prop="id" label="ID" width="80" /><el-table-column prop="store_name" label="商品" /><el-table-column label="操作" width="90"><template #default="{row}"><el-button :disabled="productsLoading" @click="chooseProduct(row.id)">选择</el-button></template></el-table-column></el-table></el-dialog>
    </template>
  </main>
</template>
<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import {ElMessageBox} from 'element-plus';
import {getToken,getAdminSession} from '@/utils/auth';
import SeckillActivityImagePicker from '@/pages/activity/SeckillActivityImagePicker.vue';
import {operationalOptions,operationalList,operationalForm,operationalFullGroup,operationalWrite,operationalReceipt,operationalProducts,type OperationalAction,type OperationalOption,type OperationalRow,type OperationalValues} from '@/api/operationalGroupData';
import {operationalGroupDataState} from '@/utils/operationalGroupDataState';
const sessionEpoch=ref(0),identity=()=>`${getToken()??''}:${JSON.stringify(getAdminSession())}`;
const permitted=(key:string)=>{sessionEpoch.value;const session=getAdminSession();return !!getToken()&&(session?.userInfo.level===0||!!session?.uniqueAuth.includes(key));};
const canView=computed(()=>permitted('operational_group.view')||permitted('operational_group.manage')),canManage=computed(()=>permitted('operational_group.manage')),canSelectProduct=computed(()=>permitted('product.view'));
const pendingKey=(key:string)=>`admin-operational-pending:${key}`;
const workflow=operationalGroupDataState({identity,manage:()=>canManage.value,list:operationalList,mutate:operationalWrite,receipt:operationalReceipt,savePending:(key,action)=>{if(action)localStorage.setItem(pendingKey(key),JSON.stringify(action));else localStorage.removeItem(pendingKey(key));}},value=>reactive(value) as typeof value),state=workflow.state;
const options=ref<OperationalOption[]>([]),dialog=ref(false),bulkDialog=ref(false),formLoading=ref(false),formRevision=ref(''),preview=ref({reference:'',url:''});
const empty=():OperationalValues&{id:number}=>({id:0,img:'',comment:'',link:'',sort:1,status:1}),form=reactive(empty()),bulk=ref<Array<OperationalValues&{key:string}>>([]);
const locked=computed(()=>state.busy||state.loading||!!state.pending||state.revoked),draftPreview=computed(()=>form.img===preview.value.reference?preview.value.url:/^(https:\/\/|\/(?!\/))/i.test(form.img)&&!form.img.startsWith('/api/assets/')?form.img:'');
let requestSerial=0,alive=true;const fieldLabel=(key:string,fallback:string)=>state.snapshot?.fields.find(field=>field.title===key)?.name??fallback;
function clearDraft(){requestSerial++;formLoading.value=false;dialog.value=bulkDialog.value=productDialog.value=false;Object.assign(form,empty());formRevision.value='';preview.value={reference:'',url:''};bulk.value=[];products.value=[];productKeyword.value=productError.value='';}
function storageChanged(event:StorageEvent){if(event.key===null||event.key==='admin_token'||event.key==='admin_session')sessionChanged();}
function restore(){const raw=localStorage.getItem(pendingKey(identity()));if(!raw)return;try{if(raw.length>256*1024)throw Error('待确认内容超过容量');const action=JSON.parse(raw) as OperationalAction;if(!['create','update','status','delete','replace'].includes(action.operation)||!action.input||!options.value.some(option=>option.config_name===action.input.config_name)||!/^[a-f0-9]{64}$/.test(action.input.expected_revision)||!/^[a-f0-9-]{36}$/.test(action.input.request_id)||!Number.isSafeInteger(action.id)||action.id<0)throw Error('待确认请求格式异常');workflow.restore(action);}catch{state.error='本地待确认请求异常，请维护核对，已暂停新写入';state.revoked=true;}}
function sessionChanged(){sessionEpoch.value++;workflow.reset();clearDraft();void refresh(true);}
watch(()=>state.revoked,value=>{if(value)clearDraft();},{flush:'sync'});
async function refresh(recover=false){if(!canView.value||state.revoked)return;const key=identity(),serial=++requestSerial;
  try{const result=await operationalOptions();if(!alive||key!==identity()||serial!==requestSerial)return;if(!Array.isArray(result)||result.length!==6)throw Error('运营图片组选项资料不完整');options.value=result;if(recover)restore();await workflow.load();}catch(error){if(alive&&key===identity()&&serial===requestSerial)workflow.reject(error);}}
async function changeGroup(){if(locked.value)return;state.page=1;clearDraft();await workflow.load();}
async function query(){if(!locked.value){state.page=1;await workflow.load();}}
async function pageChanged(page:number){if(!locked.value){state.page=page;await workflow.load();}}
async function openForm(row?:OperationalRow){if(!workflow.writable()||formLoading.value)return;const key=identity(),serial=++requestSerial,name=state.name;formLoading.value=true;
  try{const snapshot=await operationalForm(name,row?.id??0);if(!alive||key!==identity()||serial!==requestSerial||!workflow.writable())return;const values=Object.fromEntries(snapshot.rules.map(rule=>[rule.field,rule.value]));if(snapshot.config_name!==name||typeof values.img!=='string'||typeof values.comment!=='string'||typeof values.link!=='string'||!/^[a-f0-9]{64}$/.test(snapshot.revision))throw Error('运营图片表单资料不完整');Object.assign(form,empty(),{id:row?.id??0,img:values.img,comment:values.comment,link:values.link,sort:values.sort,status:values.status});formRevision.value=snapshot.revision;preview.value={reference:form.img,url:snapshot.img_preview};dialog.value=true;}catch(error){if(key===identity()&&serial===requestSerial)workflow.reject(error);}finally{if(serial===requestSerial)formLoading.value=false;}}
function chooseImage(reference:string,url:string){if(!locked.value){form.img=reference;preview.value={reference,url};}}
const action=(operation:OperationalAction['operation'],id:number,input:Partial<OperationalAction['input']>,stamp=state.snapshot?.revision??''):OperationalAction=>({operation,id,input:{config_name:state.name,expected_revision:stamp,request_id:crypto.randomUUID(),...input}});
function valid(values:OperationalValues){return !!values.img.trim()&&!!values.comment.trim()&&!!values.link.trim()&&Number.isSafeInteger(values.sort)&&values.sort>=0&&(values.status===0||values.status===1);}
async function save(){if(!workflow.writable())return;const {id,...values}=form;if(!valid(values)){state.error='请完整填写图片、描述、链接、排序和状态';return;}if(await workflow.run(action(id?'update':'create',id,values,formRevision.value)))clearDraft();}
async function setStatus(row:OperationalRow){if(workflow.writable())await workflow.run(action('status',row.id,{status:row.status===1?0:1},row.revision));}
async function remove(row:OperationalRow){const key=identity();try{await ElMessageBox.confirm(`删除运营图片 #${row.id}？`,'确认删除',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'});if(key===identity()&&workflow.writable())await workflow.run(action('delete',row.id,{},row.revision));}catch{/* cancelled */}}
async function openBulk(){if(!workflow.writable()||formLoading.value)return;const key=identity(),serial=++requestSerial,name=state.name;formLoading.value=true;try{const group=await operationalFullGroup(name);if(key!==identity()||serial!==requestSerial||!workflow.writable())return;if(group.config_name!==name||group.count!==group.list.length||group.count>100||group.list.some(row=>!row.editable))throw Error('整组编辑需要完整可编辑的0至100条记录，请先整理历史内容');bulk.value=group.list.map(row=>({key:crypto.randomUUID(),img:row.img[0],comment:row.comment,link:row.link,sort:row.sort,status:row.status as 0|1}));formRevision.value=group.revision;bulkDialog.value=true;}catch(error){if(key===identity()&&serial===requestSerial)workflow.reject(error);}finally{if(serial===requestSerial)formLoading.value=false;}}
function addBulk(){if(!locked.value&&bulk.value.length<100){const {id:_id,...values}=empty();bulk.value.push({...values,key:crypto.randomUUID()});}}
function move(index:number,direction:number){if(locked.value)return;const target=index+direction;if(target<0||target>=bulk.value.length)return;const [entry]=bulk.value.splice(index,1);bulk.value.splice(target,0,entry);}
async function saveBulk(){if(!workflow.writable())return;const values=bulk.value.map(({key:_key,...values})=>({...values}));if(values.some(value=>!valid(value))){state.error='请完整填写每张图片的内容';return;}const key=identity();try{await ElMessageBox.confirm(values.length?`替换本组全部记录为这 ${values.length} 张图片？原ID将改变。`:'确认清空本组全部图片？','确认整组替换',{confirmButtonText:'保存整组',cancelButtonText:'取消',type:'warning'});if(key===identity()&&workflow.writable()&&await workflow.run(action('replace',0,{data:values},formRevision.value)))clearDraft();}catch{/* cancelled */}}
async function retryPending(){if(await workflow.retry())clearDraft();}
async function readReceipt(){if(await workflow.reconcile())clearDraft();}
function cancelEditor(){if(state.busy)return;if(state.pending){dialog.value=bulkDialog.value=false;return;}clearDraft();}
function closeDialog(done:()=>void){if(!state.busy)done();}
const productDialog=ref(false),productsLoading=ref(false),productKeyword=ref(''),productError=ref(''),products=ref<Array<{id:number;store_name:string}>>([]);let productTarget=-1,productSerial=0;
async function openProducts(index:number){if(locked.value||!canSelectProduct.value)return;productTarget=index;productDialog.value=true;await searchProducts();}
async function searchProducts(){if(!productDialog.value||!canSelectProduct.value)return;const key=identity(),serial=++productSerial;productsLoading.value=true;productError.value='';try{const result=await operationalProducts(productKeyword.value);if(key!==identity()||serial!==productSerial||!productDialog.value)return;if(!Array.isArray(result.list)||result.list.some(row=>!Number.isInteger(row.id)||row.id<=0||typeof row.store_name!=='string'))throw Error('商品选择资料不完整');products.value=result.list;}catch(error){if(key===identity()&&serial===productSerial)productError.value=(error as Error).message;}finally{if(serial===productSerial)productsLoading.value=false;}}
function chooseProduct(id:number){if(locked.value||!canSelectProduct.value)return;const link=`/pages/goods_details/index?id=${id}`;if(productTarget===-1)form.link=link;else if(bulk.value[productTarget])bulk.value[productTarget].link=link;productDialog.value=false;}
onMounted(()=>{window.addEventListener('admin-session-changed',sessionChanged);window.addEventListener('admin-auth-expired',sessionChanged);window.addEventListener('storage',storageChanged);void refresh(true);});onUnmounted(()=>{alive=false;requestSerial++;productSerial++;workflow.reset();window.removeEventListener('admin-session-changed',sessionChanged);window.removeEventListener('admin-auth-expired',sessionChanged);window.removeEventListener('storage',storageChanged);});
defineExpose({state,workflow,form,dialog,bulkDialog,bulk,openForm,save,openBulk,saveBulk,addBulk,move,cancelEditor,retryPending,readReceipt,sessionChanged,refresh,chooseImage,openProducts,chooseProduct});
</script>
<style scoped>
.operational-page{max-width:1440px;margin:auto}.page-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:22px}.page-head h2{font-size:24px;margin:0 0 8px}.page-head p,.hint{font-size:14px;line-height:1.7;color:#64748b}.content-panel{padding:20px;border:1px solid #e2e8f0;border-radius:10px;background:#fff;margin-top:16px}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.toolbar .el-select{width:210px}.toolbar .el-select:nth-child(2){width:130px}.table-scroll{overflow:auto}.table-scroll .el-table{min-width:1100px}.banner-image{width:125px;height:60px}.draft-image{width:160px;height:85px;margin:12px 10px 0 0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.bulk-card{border:1px solid #e2e8f0;border-radius:8px;padding:16px;margin:16px 0}.bulk-card header{display:flex;gap:12px;align-items:center;justify-content:space-between;margin-bottom:16px}.recovery{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.recovery .el-button{margin-left:0}.el-alert{margin-bottom:12px}.el-pagination{margin-top:18px}@media(max-width:760px){.content-panel{padding:14px}.page-head h2{font-size:21px}.toolbar{gap:8px}.toolbar .el-select{width:100%}.toolbar .el-select:nth-child(2){width:140px}.form-grid{grid-template-columns:1fr;gap:0}.bulk-card{padding:12px}.bulk-card header{align-items:flex-start;flex-direction:column}.bulk-card header .el-button{margin-left:0}.bulk-card header div{display:flex;gap:6px;flex-wrap:wrap}}
</style>
